      timeout: 20_000,
    });
    await expect(
      page.getByRole('heading', {
        exact: true,
        level: 1,
        name: savedEditableTitle,
      }),
    ).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(savedEditableDescription)).toBeVisible();
    await expect(
