test.use({ storageState: adminStateFile });

const eventOptionEditorByTitle = async (
  page: Page,
  title: string,
): Promise<Locator> => {
  const editors = page.locator('app-event-registration-option-editor');
  const titleInputs = editors.getByRole('textbox', {
    exact: true,
    name: 'Sign-up choice name',
  });
  let matchingIndex = -1;

  await expect
    .poll(
      async () => {
        const titles = await titleInputs.evaluateAll((elements) =>
          elements.map((element) => {
            if (!(element instanceof HTMLInputElement)) {
              throw new Error('Expected an event option title input');
            }
            return element.value;
          }),
        );
        matchingIndex = titles.indexOf(title);
        return matchingIndex;
      },
      {
        message: `Expected event registration option "${title}"`,
    interruptRequested = true;
    process.kill(process.pid, 'SIGINT');
  });
}

// Playwright API step titles can contain entered values. Keep the default
// reporter set non-persistent so Auth0 passwords and protected provider
// identifiers are not serialized to a local HTML report.
const reporters = resolvePlaywrightReporters({
  ci: environment.CI,
  listOnly,
});

export default defineConfig({
  /* Focused or flaky tests are never an acceptable local or CI result. */
  failOnFlakyTests: true,
  forbidOnly: true,
  ...(environment.CI && { maxFailures: 1 }),
  /* Run tests in files in parallel */
  fullyParallel: true,
  // Downstream reporters must never print raw worker stdout/stderr. The first
  // reporter emits the same chunks after exact protected-value redaction.
  quiet: true,
  // Avoid launching enough macOS browser app bundles at once to deadlock
  // LaunchServices before Playwright can connect to Chromium's debug pipe.
  workers: environment.CI ? 1 : 4,
  /* Configure projects for major browsers */
  projects: [
    {
      name: 'database-setup',
          persist-credentials: false
          ref: ${{ github.sha }}

      - name: Setup Bun
        uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2.2.0
        with:
          bun-version: "1.4.4"

      - name: Setup Node
        uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: "24.22.1"

      - name: Install dependencies
        env:
          FONT_AWESOME_TOKEN: ${{ secrets.FONT_AWESOME_TOKEN }}
        run: |
          for attempt in 1 2 3; do
            if bun install --frozen-lockfile; then
              exit 0
            fi
            if [ "${attempt}" -eq 3 ]; then
              echo "::error::Dependency installation failed after 3 attempts"
              exit 1
            fi
            retry_delay_seconds=$((attempt * 15))
            echo "::warning::Dependency installation attempt ${attempt} failed; retrying in ${retry_delay_seconds}s"
            sleep "${retry_delay_seconds}"
          done

      - name: Install Playwright browsers
        run: bunx playwright install --with-deps chromium

      - name: Pull Docker images (compose)
        env:
          FONT_AWESOME_TOKEN: ${{ secrets.FONT_AWESOME_TOKEN }}
        run: docker compose pull

      - name: Build Docker images (compose)
        env:
          FONT_AWESOME_TOKEN: ${{ secrets.FONT_AWESOME_TOKEN }}
        run: docker compose build --pull

      - name: Start Docker stack for E2E
        env:
          FONT_AWESOME_TOKEN: ${{ secrets.FONT_AWESOME_TOKEN }}
          STRIPE_API_KEY: ${{ secrets.STRIPE_TEST_API_KEY }}
        run: |
          docker compose down --timeout 60 --remove-orphans
          docker compose up -d db mailpit minio stripe minio-init
          for _ in $(seq 1 60); do
            if docker compose exec -T db pg_isready -h 127.0.0.1 -p 5432 -U "${POSTGRES_USER}" -d "${POSTGRES_DB}" >/dev/null 2>&1; then
              echo "Database is reachable"
              exit 0
            fi
            sleep 2
          done
          echo "::error::Database did not become reachable within 120 seconds"
          docker compose ps
          bash helpers/testing/collect-docker-diagnostics.sh --tail=100
          exit 1

      - name: Start application and polling worker containers
        env:
          CLIENT_ID: ${{ secrets.CLIENT_ID }}
          CLIENT_SECRET: ${{ secrets.CLIENT_SECRET }}
          FONT_AWESOME_TOKEN: ${{ secrets.FONT_AWESOME_TOKEN }}
          PUBLIC_GOOGLE_MAPS_API_KEY: ${{ secrets.PUBLIC_GOOGLE_MAPS_API_KEY }}
          SECRET: ${{ secrets.SECRET }}
          STRIPE_API_KEY: ${{ secrets.STRIPE_TEST_API_KEY }}
          STRIPE_WEBHOOK_SECRET: ${{ secrets.STRIPE_WEBHOOK_SECRET }}
        run: docker compose up -d worker evorto

      - name: Wait for application
        env:
          FONT_AWESOME_TOKEN: ${{ secrets.FONT_AWESOME_TOKEN }}
        run: |
          ready_url="${BASE_URL}${APP_READY_PATH}"
          for _ in $(seq 1 60); do
            ready_status="$(curl --silent --show-error --output /dev/null --write-out '%{http_code}' "${ready_url}" || true)"
            if [ "${ready_status}" = "204" ]; then
